const raw = $input.item.json || {};
const extracted = raw.extracted_params || {};

const intent = (raw.intent || raw.downstream_command || 'BIBLE_CHAT').toString().toUpperCase().trim();
const rawText = (raw.rawText || raw.userPrompt || raw.text || '').toString().trim();
const userPrompt = (raw.userPrompt || raw.rawText || '').toString().trim();
const project_id = raw.project_id || null;
const project_name = raw.project_name || 'Active Anime Project';
const current_season = Number(raw.current_season || extracted.season_no || 1);
const sessionId = (raw.sessionId || `sess_${$execution.id}`).toString();
const modality = (raw.modality || 'text_only').toString();

if (!project_id) {
  throw new Error('WF-01 Error: project_id is required to hydrate or mutate Story Bible state.');
}

return {
  json: {
    intent,
    rawText,
    userPrompt,
    project_id,
    project_name,
    current_season,
    sessionId,
    modality
  }
};

const triggerCtx = $('Normalize Trigger Input').item.json;

function cleanRows(nodeName, requiredField) {
  try {
    const items = $(nodeName).all().map(i => i.json);
    const rows = [];
    for (const entry of items) {
      if (Array.isArray(entry)) {
        for (const r of entry) {
          if (r && r[requiredField] !== undefined) rows.push(r);
        }
      } else if (entry && entry[requiredField] !== undefined) {
        rows.push(entry);
      }
    }
    return rows;
  } catch (e) {
    return [];
  }
}

const projectRows = cleanRows('Supabase: Fetch Existing Bible', 'id');
const projectRecord = projectRows[0] || {};
const existingBible = projectRecord.story_bible || {};
const resolvedSeason = Number(projectRecord.current_season || triggerCtx.current_season || 1);

const existingCharacters = cleanRows('Supabase: Fetch Existing Characters', 'character_code');
const existingStatus = cleanRows('Supabase: Fetch Character Status', 'character_code');
const existingRules = cleanRows('Supabase: Fetch Story Rules', 'rule_code');
const existingArcs = cleanRows('Supabase: Fetch Character Arcs', 'arc_name');
const existingPowers = cleanRows('Supabase: Fetch Power System', 'power_name');
const existingRelationships = cleanRows('Supabase: Fetch Relationships', 'char_a_code');
const existingLocations = cleanRows('Supabase: Fetch Locations', 'name');
const existingArtifacts = cleanRows('Supabase: Fetch Artifacts', 'artifact_code');
const availableVoices = cleanRows('Supabase: Fetch Available Voices', 'voice_id');

const fallbackVoices = availableVoices.length > 0 ? availableVoices : [
  { provider: 'Svara TTS', voice_id: 'svara_hi_male_hero_01', voice_name: 'Aarav Heroic', gender: 'male', language: 'hi' },
  { provider: 'Svara TTS', voice_id: 'svara_hi_female_lead_01', voice_name: 'Meera Fierce', gender: 'female', language: 'hi' },
  { provider: 'Supertonic TTS', voice_id: 'supertonic_hi_male_deep_02', voice_name: 'Vikram Villain', gender: 'male', language: 'hi' },
  { provider: 'Supertonic TTS', voice_id: 'supertonic_hi_female_calm_02', voice_name: 'Tara Mystic', gender: 'female', language: 'hi' }
];

const charSummary = existingCharacters.length > 0
  ? existingCharacters.map(c => `- ${c.character_code} (${c.name}): ref_v${c.reference_version || 1}, voice=${c.voice_config?.voice_id || 'unassigned'}`).join('\n')
  : 'None (Fresh Project)';

const voiceSummary = fallbackVoices.map(v => `- voice_id: "${v.voice_id}" | provider: "${v.provider}" | name: "${v.voice_name}" | gender: "${v.gender}" | lang: "${v.language}"`).join('\n');

const loreSummary = [
  `Existing Story Bible Keys: ${Object.keys(existingBible).join(', ') || 'Empty'}`,
  `Character Status Rows: ${existingStatus.length}`,
  `Story Rules: ${existingRules.map(r => r.rule_code).join(', ') || 'None'}`,
  `Character Arcs: ${existingArcs.map(a => a.arc_name).join(', ') || 'None'}`,
  `Power System: ${existingPowers.map(p => p.power_name).join(', ') || 'None'}`,
  `Relationships: ${existingRelationships.length}`,
  `Locations: ${existingLocations.map(l => l.name).join(', ') || 'None'}`,
  `Artifacts: ${existingArtifacts.map(a => a.artifact_code).join(', ') || 'None'}`
].join('\n');

const isExplicitSave = triggerCtx.intent === 'SAVE_BIBLE' || /\b(save\s*karo|lock\s*karo|save\s*bible|lock\s*bible|bible\s*save|finalize\s*karo|db\s*me\s*save)\b/i.test(triggerCtx.rawText);
const operationRoute = isExplicitSave ? 'BIBLE_SAVE' : 'BIBLE_CHAT';

const styleMeta = $('When Executed by Another Workflow').first().json.project_style || {};
const visualStyle = styleMeta.visual_style || 'ANIME';
const styleProfile = styleMeta.profile || {};
const stylePrefix = styleProfile.prompt_prefix || (visualStyle === 'REALISTIC' ? 'photorealistic, cinematic lighting, 8k, raw photo' : 'anime, cel shaded, highly detailed, masterpiece');

  `=== VISUAL STYLE: ${visualStyle} ===`,
  `PREFIX: ${stylePrefix}`,
const hydratedContextText = [
  `=== PROJECT CONTEXT: ${projectRecord.name || triggerCtx.project_name} (Season ${resolvedSeason}) ===`,
  `=== EXISTING CHARACTERS (DO NOT CREATE DUPLICATE CODES) ===`,
  charSummary,
  `=== ACTIVE VOICE CATALOG (Rule 39: Assign strictly from this list) ===`,
  voiceSummary,
  `=== SUPPORTING LORE SUMMARY ===`,
  loreSummary,
  `=== CURRENT STORY BIBLE JSON ===`,
  JSON.stringify(existingBible)
].join('\n\n');

return {
  json: {
    ...triggerCtx,
    current_season: resolvedSeason,
    operation_route: operationRoute,
    existing_bible: existingBible,
    existing_characters: existingCharacters,
    available_voices: fallbackVoices,
    hydrated_context_text: hydratedContextText
  }
};

