parameters.jsCode:
const ctx = $('Context Builder').item.json;
const llmRaw = $input.item.json;
const availableVoices = ctx.available_voices || [];
const nowIso = $now.toISOString();

let parsed = null;
try {
  const content = llmRaw?.choices?.[0]?.message?.content;
  if (content) {
    const cleanStr = content.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
    parsed = JSON.parse(cleanStr);
  }
} catch (e) {
  parsed = null;
}

if (!parsed || typeof parsed !== 'object') {
  parsed = {
    route_mode: ctx.operation_route,
    chat_response: 'Bhai, LLM response parse karne me issue aaya, par maine existing Story Bible state preserve rakha hai.',
    change_summary: 'Fallback state preservation',
    bible: ctx.existing_bible || {},
    characters: [], arcs: [], powers: [], relationships: [], locations: [], artifacts: [], rules: []
  };
}

const finalRouteMode = (ctx.operation_route === 'BIBLE_SAVE' || parsed.route_mode === 'BIBLE_SAVE') ? 'BIBLE_SAVE' : 'BIBLE_CHAT';
const rawCharacters = Array.isArray(parsed.characters) ? parsed.characters : [];

const normalizedCharacters = rawCharacters.map((char, idx) => {
  const charCode = (char.character_code || `CHAR_${String(idx + 1).padStart(3, '0')}`).toString().toUpperCase().trim();
  const charName = (char.name || charCode).toString().trim();
  const charGender = (char.gender || 'male').toString().toLowerCase().trim() === 'female' ? 'female' : 'male';

  const rawDna = (char.visual_dna && typeof char.visual_dna === 'object') ? char.visual_dna : {};
  const validatedVisualDna = {
    face: (rawDna.face || 'Sharp anime facial structure').toString(),
    hair: (rawDna.hair || 'Stylized layered anime hair').toString(),
    clothing: (rawDna.clothing || 'Signature tactical anime attire').toString(),
    weapons: (rawDna.weapons || 'None').toString(),
    color_palette: (rawDna.color_palette || 'High-contrast cinematic tones').toString(),
    ...rawDna
  };

  let matchedVoice = availableVoices.find(v => v.voice_id === char.voice_id);
  if (!matchedVoice) {
    matchedVoice = availableVoices.find(v => (v.gender || '').toLowerCase() === charGender) || availableVoices[0] || {
      provider: 'Svara TTS', voice_id: charGender === 'female' ? 'svara_hi_female_lead_01' : 'svara_hi_male_hero_01', voice_name: 'Default Voice', gender: charGender, language: 'hi'
    };
  }

  const providerName = (matchedVoice.provider || 'Svara TTS').toString();
  const voiceConfig = {
    voice_id: matchedVoice.voice_id,
    voice_provider: providerName,
    voice_model: char.voice_config?.voice_model || (providerName.toLowerCase().includes('supertonic') ? 'supertonic-v1-hi' : 'svara-v2-hi'),
    language: matchedVoice.language || 'hi',
    gender: charGender,
    pitch: Number(char.voice_config?.pitch || 1.0),
    speed: Number(char.voice_config?.speed || 1.0),
    version: 1,
    status: 'pending_approval',
    emotion_profile: {
      neutral: { pitch: 1.00, rate: 1.00 }, anger: { pitch: 0.95, rate: 1.10 },
      joy: { pitch: 1.05, rate: 1.05 }, sadness: { pitch: 0.90, rate: 0.90 }, fear: { pitch: 1.02, rate: 1.08 }
    },
    assigned_at: nowIso
  };

  return {
    character_code: charCode, name: charName, gender: charGender, visual_dna: validatedVisualDna,
    voice_config: voiceConfig, source: 'MANUAL', validation_status: 'PENDING', reference_version: 1
  };
});

return {
  json: {
    ...ctx, operation_route: finalRouteMode,
    chat_response: parsed.chat_response || 'Story Bible update ready!',
    change_summary: parsed.change_summary || 'Updated Story Bible via WF-01',
    bible_payload: {
      bible: (parsed.bible && Object.keys(parsed.bible).length > 0) ? parsed.bible : ctx.existing_bible,
      characters: normalizedCharacters,
      arcs: Array.isArray(parsed.arcs) ? parsed.arcs : [],
      powers: Array.isArray(parsed.powers) ? parsed.powers : [],
      relationships: Array.isArray(parsed.relationships) ? parsed.relationships : [],
      locations: Array.isArray(parsed.locations) ? parsed.locations : [],
      artifacts: Array.isArray(parsed.artifacts) ? parsed.artifacts : [],
      rules: Array.isArray(parsed.rules) ? parsed.rules : []
    }
  }
};

const base = $('Voice Profiler & Visual DNA Validator').item.json;
const project_id = base.project_id;
const payload = base.bible_payload;

const characters_db = (payload.characters || []).map(c => ({
  project_id, character_code: c.character_code, name: c.name, visual_dna: c.visual_dna,
  voice_config: c.voice_config, source: 'MANUAL', validation_status: 'PENDING', reference_version: 1
}));

const char_ref_history_db = (payload.characters || []).map(c => ({
  project_id, character_code: c.character_code, reference_version: 1, visual_dna: c.visual_dna,
  valid_from_episode: 0, valid_to_episode: null, reason: 'Initial Bible Creation'
}));

const char_status_db = (payload.characters || []).map(c => ({
  project_id, character_code: c.character_code, status: 'alive', status_changed_ep: 0
}));

const char_status_history_db = (payload.characters || []).map(c => ({
  project_id, character_code: c.character_code, old_status: null, new_status: 'alive', episode_no: 0, reason: 'Initial Bible Creation'
}));

const char_arcs_db = (payload.arcs || []).map(a => ({
  project_id, character_code: a.character_code || (characters_db[0]?.character_code || 'CHAR_001'),
  arc_name: a.arc_name || 'Main Character Arc', current_stage: a.current_stage || 'Introduction',
  stages: Array.isArray(a.stages) ? a.stages : [], flaw: a.flaw || 'Internal conflict', goal: a.goal || 'Primary objective'
}));

const powers_db = (payload.powers || []).map(p => ({
  project_id, power_name: p.power_name || 'Core Energy System',
  power_level: parseInt(p.power_level, 10) || 1, abilities: Array.isArray(p.abilities) ? p.abilities : [], limitations: Array.isArray(p.limitations) ? p.limitations : []
}));

const relationships_db = (payload.relationships || []).map(r => ({
  project_id, char_a_code: r.char_a_code || 'CHAR_001', char_b_code: r.char_b_code || 'CHAR_002', trust_level: Number(r.trust_level ?? 50)
}));

const locations_db = (payload.locations || []).map((l, idx) => ({
  project_id, location_code: l.location_code || `LOC_${String(idx + 1).padStart(3, '0')}`,
  name: l.name || `Location ${idx + 1}`, visual_description: l.visual_description || 'Cinematic anime environment'
}));

const artifacts_db = (payload.artifacts || []).map((art, idx) => ({
  project_id, artifact_code: art.artifact_code || `ART_${String(idx + 1).padStart(3, '0')}`,
  name: art.name || `Artifact ${idx + 1}`, powers: Array.isArray(art.powers) ? art.powers : [],
  current_owner_code: art.owner || (characters_db[0]?.character_code || null)
}));

const rules_db = (payload.rules || []).map((rule, idx) => ({
  project_id, rule_code: rule.rule_code || `RULE_${String(idx + 1).padStart(3, '0')}`,
  rule_text: rule.rule_text || 'World canon rule', priority: String(rule.priority ?? 'high'), tags: Array.isArray(rule.tags) ? rule.tags : []
}));

return {
  json: {
    ...base,
    db_batches: { characters_db, char_ref_history_db, char_status_db, char_status_history_db, char_arcs_db, powers_db, relationships_db, locations_db, artifacts_db, rules_db }
  }
};

const state = $('Voice Profiler & Visual DNA Validator').item.json;
const payload = state.bible_payload;
const isSaved = state.operation_route === 'BIBLE_SAVE';
const chars = payload.characters || [];

const voiceAssignmentsText = chars.length > 0
  ? chars.map(c => `• ${c.character_code} (${c.name}) -> Voice: ${c.voice_config.voice_id} [${c.voice_config.status}]`).join('\n')
  : '• Koi naya character assign nahi hua.';

let finalMessage = '';
if (isSaved) {
  finalMessage = [
    `✅ **WF-01: Story Bible & Universe Successfully Saved!**`,
    `📁 **Project:** ${state.project_name} (\`${state.project_id}\`) | **Season:** ${state.current_season}`,
    `📊 **Saved Entities:** ${chars.length} Characters | ${payload.rules?.length || 0} Rules | ${payload.powers?.length || 0} Powers | ${payload.locations?.length || 0} Locations`,
    `🎙️ **Rule 39 Voice Assignments:**\n${voiceAssignmentsText}`,
    `💬 **Architect Note:** ${state.chat_response}`
  ].join('\n');
} else {
  finalMessage = [
    `🧠 **WF-01: Bible Architect (Brainstorming Mode)**`,
    state.chat_response,
    chars.length > 0 ? `🎙️ **Draft Voice Previews:**\n${voiceAssignmentsText}\n` : '',
    `💡 *Tip: Jab universe lock karne ke liye ready hon, bas "save karo" ya "#save_bible" bol dena!*`
  ].filter(Boolean).join('\n');
}

return {
  json: {
    ok: true, status: isSaved ? 'BIBLE_SAVED' : 'BIBLE_CHAT_COMPLETED', workflow_name: 'WF-01', execution_id: $execution.id,
    project_id: state.project_id, project_name: state.project_name, operation_route: state.operation_route,
    counts: { characters: chars.length, rules: payload.rules?.length || 0, powers: payload.powers?.length || 0, locations: payload.locations?.length || 0, arcs: payload.arcs?.length || 0, relationships: payload.relationships?.length || 0, artifacts: payload.artifacts?.length || 0 },
    output: finalMessage, text: finalMessage
  }
};
